const lockTerritoryArea = `-- name: LockTerritoryArea :exec
SELECT pg_advisory_xact_lock(
    hashtextextended('territory:' || $1::bigint::text || ':' || $2::bigint::text, 0)
)
`

type LockTerritoryAreaParams struct {
	BrandID   int64 `json:"brand_id"`
	CountryID int64 `json:"country_id"`
}

// Serializes territory writes of one (brand, country) inside a transaction.
func (q *Queries) LockTerritoryArea(ctx context.Context, arg LockTerritoryAreaParams) error {
	_, err := q.db.Exec(ctx, lockTerritoryArea, arg.BrandID, arg.CountryID)
	return err
}

const resolveTerritory = `-- name: ResolveTerritory :one
SELECT t.id, t.uuid, t.level, t.organization_id,
       o.uuid AS organization_uuid, o.name AS organization_name
FROM territories t
JOIN organizations o ON o.id = t.organization_id AND o.deleted_at IS NULL AND o.type = 'distributor'
WHERE t.brand_id = $1
  AND t.country_id = $2
  AND (t.province_id IS NULL OR t.province_id = $3::bigint)
  AND (t.district_id IS NULL OR t.district_id = $4::bigint)
ORDER BY (t.district_id IS NOT NULL) DESC, (t.province_id IS NOT NULL) DESC
LIMIT 1
`

type ResolveTerritoryParams struct {
	BrandID    int64       `json:"brand_id"`
	CountryID  int64       `json:"country_id"`
	ProvinceID pgtype.Int8 `json:"province_id"`
	DistrictID pgtype.Int8 `json:"district_id"`
}

type ResolveTerritoryRow struct {
	ID               int64       `json:"id"`
	Uuid             uuid.UUID   `json:"uuid"`
	Level            pgtype.Text `json:"level"`
	OrganizationID   int64       `json:"organization_id"`
	OrganizationUuid uuid.UUID   `json:"organization_uuid"`
	OrganizationName string      `json:"organization_name"`
}

// The most specific territory covering an address (district > province >
// country) whose distributor is live.
func (q *Queries) ResolveTerritory(ctx context.Context, arg ResolveTerritoryParams) (ResolveTerritoryRow, error) {
	row := q.db.QueryRow(ctx, resolveTerritory,
		arg.BrandID,
		arg.CountryID,
		arg.ProvinceID,
		arg.DistrictID,
	)
	var i ResolveTerritoryRow
	err := row.Scan(
		&i.ID,
		&i.Uuid,
		&i.Level,
		&i.OrganizationID,
		&i.OrganizationUuid,
		&i.OrganizationName,
	)
	return i, err
}

