const updatePlateFormat = `-- name: UpdatePlateFormat :one
UPDATE plate_formats
SET regex = COALESCE($1, regex),
    input_mask = COALESCE($2, input_mask),
    example = COALESCE($3, example),
    country_label = COALESCE($4, country_label),
    strip_color = COALESCE($5, strip_color),
    background_color = COALESCE($6, background_color),
    text_color = COALESCE($7, text_color),
    is_active = COALESCE($8, is_active),
    sort_order = COALESCE($9, sort_order)
WHERE country_id = $10
RETURNING id, country_id, regex, input_mask, example, country_label, strip_color, background_color, text_color, is_active, sort_order, created_at, updated_at
`

type UpdatePlateFormatParams struct {
	Regex           pgtype.Text `json:"regex"`
	InputMask       pgtype.Text `json:"input_mask"`
	Example         pgtype.Text `json:"example"`
	CountryLabel    pgtype.Text `json:"country_label"`
	StripColor      pgtype.Text `json:"strip_color"`
	BackgroundColor pgtype.Text `json:"background_color"`
	TextColor       pgtype.Text `json:"text_color"`
	IsActive        pgtype.Bool `json:"is_active"`
	SortOrder       pgtype.Int4 `json:"sort_order"`
	CountryID       int64       `json:"country_id"`
}

func (q *Queries) UpdatePlateFormat(ctx context.Context, arg UpdatePlateFormatParams) (PlateFormat, error) {
	row := q.db.QueryRow(ctx, updatePlateFormat,
		arg.Regex,
		arg.InputMask,
		arg.Example,
		arg.CountryLabel,
		arg.StripColor,
		arg.BackgroundColor,
		arg.TextColor,
		arg.IsActive,
		arg.SortOrder,
		arg.CountryID,
	)
	var i PlateFormat
	err := row.Scan(
		&i.ID,
		&i.CountryID,
		&i.Regex,
		&i.InputMask,
		&i.Example,
		&i.CountryLabel,
		&i.StripColor,
		&i.BackgroundColor,
		&i.TextColor,
		&i.IsActive,
		&i.SortOrder,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
